def select_next_node(current_node, destination_node, unvisited_nodes, distance_matrix):
    if not unvisited_nodes:
        return destination_node

    def node_score(node):
        proximity = distance_matrix[current_node][node]
        progress = distance_matrix[node][destination_node]
        weight = len(unvisited_nodes) / (len(unvisited_nodes) + 1)
        variance_penalty = 0.1 * sum(
            (distance_matrix[node][n] - sum(distance_matrix[node][m] for m in unvisited_nodes - {node}) / len(unvisited_nodes - {node}))**2
            for n in unvisited_nodes - {node}
        ) / len(unvisited_nodes - {node}) if (unvisited_nodes - {node}) else 0
        return proximity + weight * (1 / (progress + 1)) + variance_penalty

    next_node = min(unvisited_nodes, key=node_score)
    return next_node

def select_next_node(current_node, destination_node, unvisited_nodes, distance_matrix):
    if not unvisited_nodes:
        return destination_node
    next_node = min(
        unvisited_nodes,
        key=lambda node: distance_matrix[current_node][node] + 0.5 * (distance_matrix[current_node][node] - distance_matrix[node][destination_node])
    )
    return next_node

